package GeneratedModel {
  private import ScalarValues::*;
  part def Controller {
    in attribute io_0 : Boolean;
    in attribute io_1 : Boolean;
    in attribute io_2 : Boolean;
    attribute previousPressed1 : Boolean := false;
    attribute previousPressed2 : Boolean := false;
    attribute previousPressed3 : Boolean := false;
    attribute holdPressedSeconds : Real := 0.0;
    attribute activeState : Integer := 0;
    perform action tick {
      first start;
      then if io_2 and not previousPressed3 {
        first start;
        then assign activeState := 3;
        then assign holdPressedSeconds := 0.0;
      }
      then if io_0 and not previousPressed1 {
        first start;
        then assign activeState := 1;
        then assign holdPressedSeconds := 0.0;
      }
      then if io_1 and not previousPressed2 {
        first start;
        then assign activeState := 2;
        then assign holdPressedSeconds := 0.0;
      }
      then if not (io_2 or io_0 or io_1) {
        first start;
        then assign holdPressedSeconds := 2.0;
      }
      then if io_2 or io_0 or io_1 {
        first start;
        then assign holdPressedSeconds := 2.0;
      }
      then assign previousPressed1 := io_0;
      then assign previousPressed2 := io_1;
      then assign previousPressed3 := io_2;
    }
    out attribute io_3 : Real = (if activeState == 1 ? 1.0 else 0.0);
    out attribute io_4 : Real = (if activeState == 2 ? 1.0 else 0.0);
    out attribute io_5 : Real = (if activeState == 3 ? 1.0 else 0.0);
    out attribute io_6 : Real = (if activeState == 1 or activeState == 2 ? 90.0 else 0.0);
    out attribute io_7 : Real = (if activeState == 2 ? 90.0 else 0.0);
  }
  part system : Controller;
}
